import{_ as n,C as i,o as t,c as l,a2 as a,b as r,w as o,a as d,E as h,a3 as c}from"./chunks/framework.Ci_RTJJ5.js";const y=JSON.parse('{"title":"10 — Overview","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/10-skill-invocation/overview.md","filePath":"chapters/10-skill-invocation/overview.md"}'),p={name:"chapters/10-skill-invocation/overview.md"};function u(m,e,g,v,b,w){const s=i("Mermaid");return t(),l("div",null,[e[1]||(e[1]=a(`<h1 id="_10-—-overview" tabindex="-1">10 — Overview <a class="header-anchor" href="#_10-—-overview" aria-label="Permalink to &quot;10 — Overview&quot;">​</a></h1><p><em>How invocation works. Read this before you write code.</em></p><hr><h2 id="invocation-is-text-substitution-not-a-tool-call" tabindex="-1">Invocation is text substitution, not a tool call <a class="header-anchor" href="#invocation-is-text-substitution-not-a-tool-call" aria-label="Permalink to &quot;Invocation is text substitution, not a tool call&quot;">​</a></h2><p>A tool call is the model&#39;s decision. A skill invocation is the person&#39;s: they type <code>/deploy staging</code>, and the agent expands it before the model sees anything.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  typed:   /deploy staging eu-west</span></span>
<span class="line"><span>  sent:    Check the tests pass, then deploy to staging in eu-west.</span></span></code></pre></div><p>Three consequences:</p><ol><li><strong>The model never sees the shorthand.</strong> It sees instructions, which is what it can act on.</li><li><strong>Expansion happens before the session records the turn.</strong> A resumed run replays what was sent, not the shorthand.</li><li><strong>An unknown name is passed through.</strong> Deleting the person&#39;s text because of a typo is worse than sending a slash command the model ignores.</li></ol><h2 id="placeholders" tabindex="-1">Placeholders <a class="header-anchor" href="#placeholders" aria-label="Permalink to &quot;Placeholders&quot;">​</a></h2><p>Two forms, often in one body:</p><table tabindex="0"><thead><tr><th>Placeholder</th><th>Replaced with</th></tr></thead><tbody><tr><td><code>$ARGUMENTS</code></td><td>everything after the skill name, as one string</td></tr><tr><td><code>$0</code>, <code>$1</code>, <code>$2</code></td><td>one whitespace-separated word, by position</td></tr><tr><td><code>$9</code> with no argument</td><td>the empty string</td></tr></tbody></table><p>Replace <code>$ARGUMENTS</code> <strong>first</strong>. Both forms start with <code>$</code>, and a positional pass that runs first can corrupt the longer token.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  args:  staging eu-west</span></span>
<span class="line"><span>  &quot;Deploy to $0 in $1. Full: $ARGUMENTS&quot;</span></span>
<span class="line"><span>  → &quot;Deploy to staging in eu-west. Full: staging eu-west&quot;</span></span></code></pre></div><p>Arguments are split on whitespace. Quoting inside an argument is not handled, and this page says so rather than implying otherwise.</p><h2 id="stacking" tabindex="-1">Stacking <a class="header-anchor" href="#stacking" aria-label="Permalink to &quot;Stacking&quot;">​</a></h2><p>One prompt can name several skills. Arguments run from the skill name to the next slash command:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  &quot;/review /deploy production eu-west&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  review  → arguments: &quot;&quot;                    (nothing before the next command)</span></span>
<span class="line"><span>  deploy  → arguments: &quot;production eu-west&quot;</span></span></code></pre></div><p>Expansion walks left to right and preserves order, because the order is the instruction. &quot;Review, then deploy&quot; and &quot;deploy, then review&quot; are different jobs.</p>`,18)),(t(),r(c,null,{default:o(()=>[h(s,{id:"mermaid-95",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20P%5B%22%2Freview%20%2Fdeploy%20production%20eu-west%22%5D%20--%3E%20W%5B%22walk%20matches%22%5D%0A%20%20%20%20W%20--%3E%20R%5B%22review%20body%3Cbr%2F%3Eargs%3A%20''%22%5D%0A%20%20%20%20W%20--%3E%20D%5B%22deploy%20body%3Cbr%2F%3Eargs%3A%20'production%20eu-west'%22%5D%0A%20%20%20%20R%20--%3E%20U%5B%22one%20user%20message%22%5D%0A%20%20%20%20D%20--%3E%20U%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h2 id="the-catalogue-is-already-there" tabindex="-1">The catalogue is already there <a class="header-anchor" href="#the-catalogue-is-already-there" aria-label="Permalink to &quot;The catalogue is already there&quot;">​</a></h2><p>Chapter 09 handles discovery and advertisement. This chapter adds one method to the same <code>Catalog</code>, and one line in <code>main</code> before the prompt becomes history. The system message does not change, and neither does the loop.</p><h2 id="what-this-chapter-does-not-do" tabindex="-1">What this chapter does not do <a class="header-anchor" href="#what-this-chapter-does-not-do" aria-label="Permalink to &quot;What this chapter does not do&quot;">​</a></h2><ul><li><strong>No scripts.</strong> A skill is instructions, not a bundled program.</li><li><strong>No named arguments.</strong> Only <code>$ARGUMENTS</code> and positional.</li><li><strong>No model-chosen invocation.</strong> The person types the command.</li></ul><h2 id="self-check" tabindex="-1">Self-check <a class="header-anchor" href="#self-check" aria-label="Permalink to &quot;Self-check&quot;">​</a></h2><ol><li>Who decides to invoke a skill: the model or the person? <em>(Invocation is text substitution, not a tool call)</em></li><li>Why is <code>$ARGUMENTS</code> replaced before <code>$0</code>? <em>(Placeholders)</em></li><li>How are arguments delimited when two skills share a prompt? <em>(Stacking)</em></li><li>What happens to a skill name that does not exist? <em>(Invocation is text substitution, not a tool call)</em></li><li>Which chapter does discovery, and which does expansion? <em>(The catalogue is already there)</em></li></ol>',6))])}const f=n(p,[["render",u]]);export{y as __pageData,f as default};
